import React, { useState, useEffect, useCallback } from 'react';
import { Plus, MessageSquare, LogOut, Sparkles, ChevronRight } from 'lucide-react';
import { useAuth } from '../../context/AuthContext';
import { sessionsAPI } from '../../services/api';
import { formatSessionDate } from '../../utils/helpers';
import { Button, Spinner } from '../ui';
import toast from 'react-hot-toast';

export default function Sidebar({ activeSessionId, onSelectSession, onNewSession }) {
  const { user, logout } = useAuth();
  const [sessions, setSessions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [creating, setCreating] = useState(false);

  const fetchSessions = useCallback(async () => {
    try {
      const res = await sessionsAPI.list();
      setSessions(res.data);
    } catch {
      toast.error('Could not load sessions');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { fetchSessions(); }, [fetchSessions]);

  const handleNew = async () => {
    setCreating(true);
    try {
      const res = await sessionsAPI.create();
      const newSession = res.data;
      setSessions(prev => [newSession, ...prev]);
      onNewSession(newSession);
    } catch {
      toast.error('Could not create session');
    } finally {
      setCreating(false);
    }
  };

  return (
    <aside style={styles.sidebar}>
      {/* Brand */}
      <div style={styles.brand}>
        <div style={styles.brandIcon}><Sparkles size={18} color="#C4B5FD" /></div>
        <span style={styles.brandName}>Solace</span>
      </div>

      {/* New session */}
      <div style={{ padding: '0 12px 12px' }}>
        <Button variant="outline" size="md" loading={creating} onClick={handleNew}
          style={{ width: '100%', justifyContent: 'flex-start', gap: '8px',
            borderColor: 'var(--border)', color: 'var(--text-secondary)' }}>
          <Plus size={16} />
          New conversation
        </Button>
      </div>

      {/* Session list */}
      <div style={styles.sessionList}>
        <p style={styles.listLabel}>Conversations</p>

        {loading ? (
          <div style={{ display: 'flex', justifyContent: 'center', padding: '32px 0' }}>
            <Spinner size={22} />
          </div>
        ) : sessions.length === 0 ? (
          <div style={styles.empty}>
            <MessageSquare size={28} color="var(--text-muted)" />
            <p style={{ fontSize: '13px', color: 'var(--text-muted)', textAlign: 'center' }}>
              No conversations yet.<br />Start one above.
            </p>
          </div>
        ) : (
          sessions.map(session => (
            <button
              key={session.id}
              onClick={() => onSelectSession(session)}
              style={{
                ...styles.sessionItem,
                ...(activeSessionId === session.id ? styles.sessionItemActive : {}),
              }}
            >
              <div style={styles.sessionIcon}>
                <MessageSquare size={14}
                  color={activeSessionId === session.id ? '#C4B5FD' : 'var(--text-muted)'} />
              </div>
              <div style={{ flex: 1, minWidth: 0 }}>
                <p style={styles.sessionTitle}>
                  {formatSessionDate(session.created_at)}
                </p>
                <p style={styles.sessionSub}>Session</p>
              </div>
              {activeSessionId === session.id && (
                <ChevronRight size={14} color="var(--accent-primary)" />
              )}
            </button>
          ))
        )}
      </div>

      {/* User footer */}
      <div style={styles.userFooter}>
        <div style={styles.avatar}>
          {(user?.email?.[0] || 'U').toUpperCase()}
        </div>
        <div style={{ flex: 1, minWidth: 0 }}>
          <p style={{ fontSize: '13px', fontWeight: 500, color: 'var(--text-primary)',
            overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
            {user?.email}
          </p>
        </div>
        <button onClick={logout} style={styles.logoutBtn} title="Sign out">
          <LogOut size={16} />
        </button>
      </div>
    </aside>
  );
}

const styles = {
  sidebar: {
    width: '260px', flexShrink: 0,
    background: 'var(--bg-card)',
    borderRight: '1px solid var(--border)',
    display: 'flex', flexDirection: 'column',
    height: '100vh',
    overflow: 'hidden',
  },
  brand: {
    display: 'flex', alignItems: 'center', gap: '10px',
    padding: '20px 16px 16px',
    borderBottom: '1px solid var(--border)',
    marginBottom: '12px',
  },
  brandIcon: {
    width: '32px', height: '32px',
    background: 'var(--accent-glow)', border: '1px solid var(--border-accent)',
    borderRadius: 'var(--radius-md)',
    display: 'flex', alignItems: 'center', justifyContent: 'center',
  },
  brandName: {
    fontSize: '16px', fontWeight: 700,
    color: 'var(--text-primary)', letterSpacing: '-0.4px',
  },
  sessionList: {
    flex: 1, overflowY: 'auto', padding: '0 12px',
  },
  listLabel: {
    fontSize: '11px', fontWeight: 600,
    color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.08em',
    padding: '0 4px', marginBottom: '6px',
  },
  sessionItem: {
    width: '100%', display: 'flex', alignItems: 'center', gap: '10px',
    padding: '9px 10px', borderRadius: 'var(--radius-md)',
    background: 'transparent', border: 'none', cursor: 'pointer',
    transition: 'background 150ms',
    marginBottom: '2px',
  },
  sessionItemActive: {
    background: 'var(--accent-glow)',
    border: '1px solid var(--border-accent)',
  },
  sessionIcon: {
    width: '28px', height: '28px',
    background: 'var(--bg-elevated)', borderRadius: 'var(--radius-sm)',
    display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0,
  },
  sessionTitle: {
    fontSize: '13px', fontWeight: 500, color: 'var(--text-primary)',
    textAlign: 'left',
  },
  sessionSub: {
    fontSize: '11px', color: 'var(--text-muted)', textAlign: 'left',
  },
  empty: {
    display: 'flex', flexDirection: 'column', alignItems: 'center',
    gap: '10px', padding: '32px 16px',
  },
  userFooter: {
    display: 'flex', alignItems: 'center', gap: '10px',
    padding: '14px 16px',
    borderTop: '1px solid var(--border)',
    background: 'var(--bg-card)',
  },
  avatar: {
    width: '32px', height: '32px', borderRadius: '50%',
    background: 'var(--accent-glow)', border: '1px solid var(--border-accent)',
    display: 'flex', alignItems: 'center', justifyContent: 'center',
    fontSize: '13px', fontWeight: 600, color: 'var(--accent-primary)', flexShrink: 0,
  },
  logoutBtn: {
    background: 'none', border: 'none', cursor: 'pointer',
    color: 'var(--text-muted)', padding: '6px', borderRadius: 'var(--radius-sm)',
    display: 'flex', transition: 'color 150ms',
  },
};
